<?php require __DIR__.'/api/schema.php';if($_SERVER['REQUEST_METHOD']==='POST'){if(strlen($_POST['senha']??'')<8)exit('Senha mínima: 8 caracteres.');$q=db()->prepare('INSERT INTO medicos(nome,crm,especialidade,email,senha_hash) VALUES(?,?,?,?,?)');$q->execute([trim($_POST['nome']),trim($_POST['crm']),trim($_POST['especialidade']),trim($_POST['email']),password_hash($_POST['senha'],PASSWORD_DEFAULT)]);header('Location:login.php');exit;}?><!doctype html><html lang="pt-BR"><head><?php require __DIR__.'/partials/head.php';?></head><body><main style="max-width:600px"><div class="panel"><h1>Instalar DrJulio</h1><form method="post"><label>Nome</label><input name="nome" required><label>CRM</label><input name="crm" required><label>Especialidade</label><input name="especialidade"><label>E-mail</label><input name="email"><label>Senha</label><input type="password" name="senha" minlength="8" required><button class="btn">Criar acesso</button></form></div></main></body></html>